        migrate_reservation_owner_activity()
        if app.config.get('ADVENTURER_S1_FIXED_REALM_CODE') == 'region_2':
            logging.getLogger(__name__).info('S1 二区固定 Runtime 跳过中央共享存活角色槽位迁移')
        else:
            realm_backfill_stats = backfill_realm_memberships()
            if realm_backfill_stats.get('inserted') or realm_backfill_stats.get('updated') or realm_backfill_stats.get('removed_legacy_reservation_rows') or realm_backfill_stats.get('preserved_legacy_region_2_rows'):
                logging.getLogger(__name__).info('S1 启动迁移两区共享存活角色槽位: %s', realm_backfill_stats)
            if realm_backfill_stats.get('conflicting_history') or realm_backfill_stats.get('membership_history_conflicts'):
                logging.getLogger(__name__).warning('S1 启动发现存活角色槽位冲突，已保持未修改: %s', realm_backfill_stats)
        migrate_ambient_npc_ai_gifts()
        migrate_observer_review_observability()
        migrate_name_history_projection()
