        lease_schema_stats = repair_narrative_lease_integrity()
        if lease_schema_stats.get('duplicate_ids_rekeyed') or lease_schema_stats.get('primary_key_added') or lease_schema_stats.get('indexes_rebuilt'):
            logging.getLogger(__name__).warning('S1 启动修复叙事租约表完整性: %s', lease_schema_stats)
        squad_schema_stats = repair_squad_integrity()
        if squad_schema_stats.get('constraints_added') or squad_schema_stats.get('constraints_reused') or squad_schema_stats.get('constraints_validated'):
            logging.getLogger(__name__).warning('S1 启动补齐纹章小队成员外键完整性: %s', squad_schema_stats)
        buyback_deadline_stats = backfill_buyback_repurchase_deadlines(hours=app.config.get('ADVENTURER_S1_APPEAL_BUYBACK_REPURCHASE_HOURS', 24))
        if buyback_deadline_stats.get('updated'):
            logging.getLogger(__name__).info('S1 启动为旧收购流水开启买回期限: %s', buyback_deadline_stats)
        S1SettingsService.sync_runtime_settings_to_app_config()
        AdventurerS1Service.backfill_last_owner_action_at()
        disband_all_legacy_normal_parties()
        committed, commit_error = db_manager.commit()
        if not committed:
            raise RuntimeError(commit_error or 'S1 启动维护提交失败')
        try:
            from plugins.adventurer_s1.services.adventurer_s1_expedition_log_category_service import backfill_missing_special_event_themes_job
            category_stats = backfill_missing_special_event_themes_job()
            if category_stats.get('processed'):
                logging.getLogger(__name__).info('S1 启动探险日志分类回填: %s', category_stats)
        except Exception:
            logging.getLogger(__name__).exception('S1 启动探险日志分类回填失败')
        try:
            from plugins.adventurer_s1.services.adventurer_s1_trait_recovery_service import run_startup_trait_recovery_repair
            repair_stats = run_startup_trait_recovery_repair()
            if repair_stats.get('cleared_stale_baselines') or repair_stats.get('settled_traits'):
                logging.getLogger(__name__).info('S1 启动特质恢复修复: %s', repair_stats)
        except Exception:
            logging.getLogger(__name__).exception('S1 启动特质恢复修复失败')
        stats = requeue_stuck_s1_ai_tasks(startup_recovery=True)
        recovered = 0
        for value in stats.values():
            if isinstance(value, dict):
                recovered += sum((int(item or 0) for item in value.values()))
            else:
                recovered += int(value or 0)
        if recovered:
            logging.getLogger(__name__).info('S1 启动 AI recovery: %s', stats)
